import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import './styles.css';
import GoogleAd from "./GoogleAd";
import { analytics } from "./firebaseConfig";
import { logEvent } from "firebase/analytics";

// Import both logo images
import logo from './checkmatewizard_transparent.png';
import logoWhite from './checkmatewizard_pure_white.png';

const LandingPage = () => {
    const [isLogoHovered, setIsLogoHovered] = useState(false);
    const [isDropdownOpen, setIsDropdownOpen] = useState(false);
    const [isMobile, setIsMobile] = useState(window.innerWidth < 1200);

    // Event listener for window resize
    useEffect(() => {
                    const handleResize = () => {
                        const isNowMobile = window.innerWidth < 1200;
                        setIsMobile(isNowMobile);
                
                        if (isNowMobile) {
                            console.log('Applying frozen class');
                            document.body.classList.add('frozen');
                        } else {
                            console.log('Removing frozen class');
                            document.body.classList.remove('frozen');
                        }
                    };
                
                    window.addEventListener('resize', handleResize);
                
                    handleResize();
                
                    return () => window.removeEventListener('resize', handleResize);
                }, []);

    useEffect(() => {
        if (analytics) {
            logEvent(analytics, "page_view", { page: "LandingPage" });
        }
    }, []);

    return (
        <div className="landingo-page">
            <header>
                            <nav>
                                <ul>
                                    <li
                                        onMouseEnter={() => setIsLogoHovered(true)}
                                        onMouseLeave={() => setIsLogoHovered(false)}
                                    >
                                        <Link to="/">
                                            <img src={isLogoHovered ? logoWhite : logo} alt="Home" style={{ height: '39px' }} />
                                        </Link>
                                    </li>
                                    {isMobile ? (
                                        <div className="navdropdown-container">
                                            <div
                                                className={`${isDropdownOpen ? 'navdropdown' : 'navdropdown'}`}
                                                onClick={() => setIsDropdownOpen(!isDropdownOpen)}
                                            >
                                                <li
                                                    className="navdropdown-header"
                                                    style={{
                            
                                                        lineHeight: '1.78',
                                                        padding: '10px 20px',
                            
                                                        fontSize: '22px',
                                                        color: 'white',
                                                    }}
                                                    
                                                >
                                                    ☰ Menu
                                                </li>
                                                {isDropdownOpen && (
                                                    <ul>
                                                        <li>
                                                            <Link
                                                                to="/blunder-punisher"
                                                                className="nav-link"
                                                                onClick={() => setIsDropdownOpen(false)}
                                                            >
                                                                Blunder Punisher
                                                            </Link>
                                                        </li>
                                                        <li>
                                                            <Link
                                                                to="/weakness-finder"
                                                                className="nav-link"
                                                                onClick={() => setIsDropdownOpen(false)}
                                                            >
                                                                Weakness Finder
                                                            </Link>
                                                        </li>
                                                        <li>
                                                            <Link
                                                                to="/analysis-board"
                                                                className="nav-link"
                                                                onClick={() => setIsDropdownOpen(false)}
                                                            >
                                                                Analysis Board
                                                            </Link>
                                                        </li>
                                                        <li>
                                                            <Link
                                                                to="/feedback"
                                                                className="nav-link"
                                                                onClick={() => setIsDropdownOpen(false)}
                                                            >
                                                                Your Feedback
                                                            </Link>
                                                        </li>
                                                    </ul>
                                                )}
                                            </div>
                                        </div>
                                    ) : (
                                        <ul>
                                            <li>
                                                <Link to="/blunder-punisher" className="prepare-link">
                                                    Blunder Punisher
                                                </Link>
                                            </li>
                                            <li>
                                                <Link to="/weakness-finder">Weakness Finder</Link>
                                            </li>
                                            <li>
                                                <Link to="/analysis-board">Analysis Board</Link>
                                            </li>
                                            <li>
                                                <Link to="/feedback">Your Feedback</Link>
                                            </li>
                                        </ul>
                                    )}
                                </ul>
                            </nav>
                        </header>

            <main>
                <section className='landing-page'>
                {/* Beta Announcement */}
                <section className="beta-announcement">
                    <h1>Welcome to the CheckmateWizard.com Beta</h1>
                    <p>We make checkmating your opponents easier than ever before!</p>
                </section>

                {/* Feature Overview */}
                <section className="feature-section">
                    <div className="feature-box">
                        <h2>Weakness Finder</h2>
                        <p>Discover openings that your play often but struggle with.</p>
                        <Link to="/weakness-finder">
                            <button className="feature-button">Try Weakness Finder</button>
                        </Link>
                    </div>

                    <div className="feature-box">
                        <h2>Blunder Punisher</h2>
                        <p>Identify common mistakes your make and learn how to fix them.</p>
                        <Link to="/blunder-punisher">
                            <button className="feature-button">Try Blunder Punisher</button>
                        </Link>
                    </div>
                </section>

                {/* Feedback Button */}
                <section className="feedback-section">
                    <p>Help us improve! Share your thoughts.</p>
                    <Link to="/feedback">
                        <button className="feedback-button">Give Feedback</button>
                    </Link>
                </section>
                </section>
            </main>

            <footer>
                <p>&copy; 2025 CheckmateWizard.com All rights reserved.</p>
            </footer>
            <GoogleAd />
        </div>
    );
};

export default LandingPage;
